import { chromium } from 'playwright';

const URL = 'http://localhost:5173/';
const browser = await chromium.launch();
const results = [];
const check = (name, cond, extra = '') => {
  results.push(`${cond ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);
};

const bodyTheme = (page) =>
  page.evaluate(() => document.body.className);
const storedValue = (page) =>
  page.evaluate(() => window.localStorage.getItem('app-theme'));
const checkedLabel = (page) =>
  page.evaluate(() => {
    const input = document.querySelector('input[type="radio"]:checked');
    return input ? input.closest('label')?.textContent?.trim() ?? input.value : null;
  });

async function clickOption(page, label) {
  await page.getByText(label, { exact: true }).click();
}

// Новый контекст = чистый localStorage.
const ctx = await browser.newContext({ colorScheme: 'light' });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(String(e)));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

await page.goto(URL);
await page.waitForSelector('input[type="radio"]');

check('default: no stored value → light', (await bodyTheme(page)).includes('_theme_light'), await bodyTheme(page));
check('default: stored value is null', (await storedValue(page)) === null);

await clickOption(page, 'Dark');
await page.waitForTimeout(100);
check('click Dark → body has dark theme', (await bodyTheme(page)).includes('_theme_dark'), await bodyTheme(page));
check('click Dark → localStorage = dark', (await storedValue(page)) === 'dark', String(await storedValue(page)));

await page.reload();
await page.waitForSelector('input[type="radio"]');
check('reload → body still dark', (await bodyTheme(page)).includes('_theme_dark'), await bodyTheme(page));
check('reload → Dark segment checked', (await checkedLabel(page)) === 'Dark', String(await checkedLabel(page)));

await clickOption(page, 'System');
await page.waitForTimeout(100);
check('click System → localStorage = system', (await storedValue(page)) === 'system');
await page.reload();
await page.waitForSelector('input[type="radio"]');
check('reload → System segment checked', (await checkedLabel(page)) === 'System', String(await checkedLabel(page)));

await clickOption(page, 'Light');
await page.reload();
await page.waitForSelector('input[type="radio"]');
check('reload → light restored', (await bodyTheme(page)).includes('_theme_light') && (await checkedLabel(page)) === 'Light');

// Невалидное значение в storage → дефолт, без падения.
await page.evaluate(() => window.localStorage.setItem('app-theme', 'purple'));
await page.reload();
await page.waitForSelector('input[type="radio"]');
check('invalid stored value → falls back to light', (await bodyTheme(page)).includes('_theme_light'), await bodyTheme(page));

// Сохранённое dark должно применяться до первого paint (без мигания): проверяем сразу после DOMContentLoaded.
await page.evaluate(() => window.localStorage.setItem('app-theme', 'dark'));
await page.reload();
await page.waitForSelector('input[type="radio"]');
check('stored dark applied on load', (await bodyTheme(page)).includes('_theme_dark'));

// Системная тема: colorScheme dark + system режим.
await page.evaluate(() => window.localStorage.setItem('app-theme', 'system'));
const darkCtx = await browser.newContext({ colorScheme: 'dark' });
const dpage = await darkCtx.newPage();
await dpage.goto(URL);
await dpage.evaluate(() => window.localStorage.setItem('app-theme', 'system'));
await dpage.reload();
await dpage.waitForSelector('input[type="radio"]');
check('system + OS dark → body dark', (await bodyTheme(dpage)).includes('_theme_dark'), await bodyTheme(dpage));
await darkCtx.close();

check('no page errors', errors.length === 0, errors.join(' | '));

console.log(results.join('\n'));
await browser.close();

